'use client';

import { useEffect, useMemo, useState } from 'react';
import { ArrowDownTrayIcon, ArrowPathIcon, ArrowTrendingUpIcon, BellAlertIcon, CheckCircleIcon, ChevronRightIcon, ClockIcon, ExclamationTriangleIcon, PlusIcon, SignalIcon, SignalSlashIcon, TrashIcon, WalletIcon } from '@heroicons/react/24/outline';
import { alerts, type CandidateStatus, type Expiry, type Order, type Payment, type PaymentMethod, type PaymentStatus, type Product, type ReceptionLine, type ReceptionStatus, type ReviewStatus, type Source, type SourceCandidate, type Supplier, type SupplierProduct, type User, type UserRole } from '@/lib/mock-data';
import { type DemoState, useDemoState } from '@/lib/demo-store';
import type { Section } from './sidebar';
import { OrderPdf } from './order-pdf';
import { alertLabel, buildAlerts, calendarIcs, DEMO_TODAY, daysUntil, effectiveStatus, type AlertKind, type AppAlert } from '@/lib/alerts';
import { AlertAgenda, AlertExpiries, Notifications } from './alert-center';
import { SupabaseStatus } from './supabase-status';
import { currentGreeting, formatDateEs, getLocalDateISO } from '@/lib/date';

const today = DEMO_TODAY;
const money = (value: number) => `$ ${value.toLocaleString('es-CO')}`;
const dateEs = (value: string) => formatDateEs(value);
const supplierName = (suppliers: Supplier[], id: string) => suppliers.find((x) => x.id === id)?.name || 'Sin proveedor';
const orderTotal = (order: Order) => order.lines.reduce((sum, line) => sum + line.price * line.quantity, 0);
const paymentMethods: PaymentMethod[] = ['efectivo', 'transferencia', 'tarjeta', 'cuenta corriente'];
const paymentStatuses: PaymentStatus[] = ['pendiente', 'parcial', 'pagado', 'vencido'];
const receptionLabels: Record<ReceptionStatus, string> = { pending: 'Pendiente', received: 'Llegó', shortage: 'Faltante', surplus: 'Sobrante', substitution: 'Sustitución' };
const roles: UserRole[] = ['Administrador', 'Compras', 'Recepción', 'Consulta'];
type State = DemoState;
type Demo = ReturnType<typeof useDemoState>;
type Mutate = (fn: (state: State) => State) => void;

function Panel({ title, subtitle, children, action }: { title: string; subtitle: string; children: React.ReactNode; action?: React.ReactNode }) { return <section className="rounded-2xl border border-white/10 bg-petroleum-900 p-5 shadow-panel"><div className="mb-5 flex flex-wrap items-start justify-between gap-4"><div><h3 className="font-bold text-white">{title}</h3><p className="mt-1 text-xs text-slate-400">{subtitle}</p></div>{action}</div>{children}</section>; }
function EmptyState({ text }: { text: string }) { return <div className="rounded-xl border border-dashed border-white/15 p-10 text-center text-sm text-slate-400">{text}</div>; }
function Field({ label, children }: { label: string; children: React.ReactNode }) { return <label className="block text-xs font-semibold text-slate-300"><span className="mb-1.5 block">{label}</span>{children}</label>; }
function Badge({ value }: { value: string }) { const color = /pagado|Llegó|Recibido|received|Confirmado|Aprobado|Activo/.test(value) ? 'badge-green' : /vencido|Faltante|shortage|Sobrante|Rechazado|Error/.test(value) ? 'badge-red' : 'badge-amber'; return <span className={color}>{value}</span>; }
function Metric({ title, value, note, color = 'cyan', icon = <ArrowTrendingUpIcon className="h-5 w-5" /> }: { title: string; value: string; note: string; color?: string; icon?: React.ReactNode }) { const colors: Record<string, string> = { cyan: 'bg-cyan-400/15 text-cyan-300', green: 'bg-emerald-400/15 text-emerald-300', amber: 'bg-amber-400/15 text-amber-300', red: 'bg-red-400/15 text-red-300' }; return <div className="rounded-2xl border border-white/10 bg-petroleum-900 p-5 shadow-panel"><span className={`inline-flex rounded-lg p-2 ${colors[color]}`}>{icon}</span><div className="mt-4 text-2xl font-bold tracking-tight text-white">{value}</div><div className="mt-1 text-sm font-semibold text-slate-300">{title}</div><div className="mt-3 text-xs text-slate-500">{note}</div></div>; }

export function Dashboard({ section, onNavigate, demo, installPromptAvailable, installed, onInstallPrompt }: { section: Section; onNavigate: (section: Section) => void; demo: Demo; installPromptAvailable: boolean; installed: boolean; onInstallPrompt: () => Promise<void> }) {
  const [toast, setToast] = useState(''); const [online, setOnline] = useState(true); const [referenceDate, setReferenceDate] = useState(DEMO_TODAY);
  useEffect(() => { setReferenceDate(getLocalDateISO()); }, []);
  useEffect(() => { const update = () => setOnline(navigator.onLine); update(); window.addEventListener('online', update); window.addEventListener('offline', update); return () => { window.removeEventListener('online', update); window.removeEventListener('offline', update); }; }, []);
  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(''), 3200); return () => window.clearTimeout(timer); }, [toast]);
  useEffect(() => { const generated = buildAlerts(demo.state, referenceDate, demo.state.alerts); if (JSON.stringify(generated) !== JSON.stringify(demo.state.alerts)) demo.update((current) => ({ ...current, alerts: generated })); }, [demo, demo.state.expiries, demo.state.orders, demo.state.alerts, referenceDate]);
  const notify = (message: string) => setToast(message);
  const restore = () => onNavigate('Configuración');
  useEffect(() => { document.querySelectorAll('button').forEach((button) => { if (button.textContent?.includes('Restaurar demo')) button.remove(); }); }, []);
  useEffect(() => { const restore = () => demo.restoreDemo(); window.addEventListener('restore-demo', restore); return () => window.removeEventListener('restore-demo', restore); }, [demo]);
  const exportPayments = () => { const rows = demo.state.payments.filter((p) => !p.cancelled).map((p) => [p.id, supplierName(demo.state.suppliers, p.supplierId), p.orderId || '', p.amount, p.date, p.method, p.status, p.reference]); const csv = ['ID,Proveedor,Pedido,Monto,Fecha,Método,Estado,Referencia', ...rows.map((row) => row.map((x) => `"${String(x).replaceAll('"', '""')}"`).join(','))].join('\n'); const link = document.createElement('a'); link.href = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })); link.download = 'pagos-control-abastecimiento.csv'; link.click(); notify('CSV de pagos descargado'); };
  const activeAlerts = demo.state.alerts.filter((alert) => effectiveStatus(alert, referenceDate) === 'activa');
  const enableBrowserNotifications = async () => { if (!('Notification' in window)) return notify('Este navegador no ofrece notificaciones; usa las alertas internas o exporta .ics.'); const permission = Notification.permission === 'default' ? await Notification.requestPermission() : Notification.permission; if (permission !== 'granted') return notify(permission === 'denied' ? 'Permiso de notificaciones denegado; usa alertas internas o exporta .ics.' : 'Permiso no concedido'); demo.update((current) => ({ ...current, alertPreferences: { ...current.alertPreferences, browser: true } })); notify('Notificaciones del navegador activadas'); };
  useEffect(() => { if (!demo.state.alertPreferences.browser || !('Notification' in window) || Notification.permission !== 'granted') return; activeAlerts.filter((alert) => !demo.state.alertPreferences.notifiedKeys.includes(alert.key)).slice(0, 1).forEach((alert) => { new Notification('ZAVRYON SYSTEMS', { body: alert.title }); demo.update((current) => ({ ...current, alertPreferences: { ...current.alertPreferences, notifiedKeys: [...current.alertPreferences.notifiedKeys, alert.key] } })); }); }, [activeAlerts, demo]);
  const content = section === 'Inicio' ? <Home state={demo.state} onNavigate={onNavigate} /> : section === 'Pedidos' ? <Orders state={demo.state} onNavigate={onNavigate} /> : section === 'Nuevo pedido' ? <NewOrder state={demo.state} update={demo.update} notify={notify} onNavigate={onNavigate} /> : section === 'Recepcion' ? <Reception state={demo.state} update={demo.update} notify={notify} /> : section === 'Proveedores llegados' ? <Arrivals state={demo.state} onNavigate={onNavigate} /> : section === 'Proveedores' ? <Suppliers state={demo.state} update={demo.update} notify={notify} /> : section === 'Catalogo' ? <Catalog state={demo.state} update={demo.update} notify={notify} /> : section === 'Fuentes' ? <Sources state={demo.state} update={demo.update} notify={notify} /> : section === 'Vencimientos' ? <AlertExpiries state={demo.state} update={demo.update} notify={notify} onNavigate={onNavigate} /> : section === 'Agenda' ? <AlertAgenda state={demo.state} update={demo.update} notify={notify} onNavigate={onNavigate} /> : section === 'Notificaciones' ? <Notifications state={demo.state} update={demo.update} notify={notify} onNavigate={onNavigate} /> : section === 'Historial' ? <History state={demo.state} /> : section === 'Economia' ? <Economy state={demo.state} onNavigate={onNavigate} /> : section === 'Pagos' ? <Payments state={demo.state} update={demo.update} notify={notify} exportCsv={exportPayments} /> : section === 'Usuarios' ? <><SupabaseStatus /><Users state={demo.state} update={demo.update} notify={notify} /></> : section === 'Configuración' ? <Settings clearLocalData={demo.clearLocalData} notify={notify} installPromptAvailable={installPromptAvailable} installed={installed} onInstallPrompt={onInstallPrompt} /> : <Generic section={section} state={demo.state} />;
  return <main className="min-w-0 flex-1"><header className="flex min-h-20 items-center justify-between border-b border-white/10 bg-petroleum-950 px-5 pl-20 lg:px-10 lg:pl-10"><div><p className="text-xs font-semibold uppercase tracking-widest text-slate-500">Fecha de referencia: 21 de septiembre 2026</p><h1 className="mt-1 text-xl font-bold text-white">Control de Abastecimiento</h1></div><div className="flex items-center gap-2"><span className={`hidden items-center gap-1 text-xs font-semibold sm:flex ${online ? 'text-emerald-300' : 'text-amber-300'}`} role="status">{online ? <SignalIcon className="h-4 w-4" /> : <SignalSlashIcon className="h-4 w-4" />}{online ? 'En línea' : 'Sin conexión'}</span><button type="button" onClick={() => onNavigate('Notificaciones')} aria-label="Abrir notificaciones" className="relative rounded-lg border border-white/10 p-2.5 text-slate-300 hover:border-cyan-300 hover:text-cyan-300"><BellAlertIcon className="h-5 w-5" />{activeAlerts.length > 0 && <span className="absolute -right-1 -top-1 min-w-4 rounded-full bg-amber-400 px-1 text-center text-[10px] font-bold text-amber-950">{activeAlerts.length}</span>}</button><button type="button" onClick={() => onNavigate('Pagos')} aria-label="Abrir pagos" className="rounded-lg border border-white/10 p-2.5 text-slate-300 hover:border-cyan-300 hover:text-cyan-300"><WalletIcon className="h-5 w-5" /></button><button type="button" onClick={() => onNavigate('Nuevo pedido')} className="button-primary flex items-center gap-2"><PlusIcon className="h-5 w-5" /><span className="hidden sm:inline">Nuevo pedido</span></button></div></header><div className="mx-auto max-w-[1500px] p-5 lg:p-10"><div className="mb-8 flex flex-wrap items-end justify-between gap-4"><div><p className="mb-2 text-sm font-semibold text-amber-300">ZAVRYON SYSTEMS · Demo local</p><h2 className="text-3xl font-bold tracking-tight text-white">{section}</h2></div><div className="flex gap-2"><button type="button" onClick={restore} className="button-secondary"><ArrowPathIcon className="h-4 w-4" /> Restaurar demo</button>{section === 'Pagos' && <button type="button" onClick={exportPayments} className="button-secondary"><ArrowDownTrayIcon className="h-4 w-4" /> Exportar CSV</button>}</div></div>{content}</div>{toast && <div role="status" className="fixed bottom-5 right-5 z-50 rounded-xl border border-cyan-300/30 bg-ink px-4 py-3 text-sm font-semibold text-white">{toast}</div>}</main>;
}

function Home({ state, onNavigate }: { state: State; onNavigate: (s: Section) => void }) { const totals = finance(state); return <><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric title="Pedidos abiertos" value={String(state.orders.filter((x) => x.status !== 'Recibido').length).padStart(2, '0')} note="Requieren seguimiento" /><Metric title="Total comprado" value={money(totals.purchased)} note="Pedidos del período" color="amber" /><Metric title="Total recibido" value={money(totals.received)} note="Unidades valorizadas" color="green" icon={<CheckCircleIcon className="h-5 w-5" />} /><Metric title="Saldo pendiente" value={money(totals.balance)} note={`${money(totals.paid)} pagado`} color="red" icon={<WalletIcon className="h-5 w-5" />} /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.65fr_1fr]"><Panel title="Pedidos recientes" subtitle="Compra, recepción y pago en un mismo vistazo" action={<button type="button" onClick={() => onNavigate('Pedidos')} className="link-button">Ver todos <ChevronRightIcon className="h-4 w-4" /></button>}><OrderTable state={state} /></Panel><Panel title="Alertas y acciones" subtitle="Lo que necesita tu atención"><div className="space-y-3">{alerts.map((a) => <div key={a.title} className="rounded-xl border border-white/10 p-3"><div className="flex gap-3"><span className="mt-0.5 h-8 w-8 shrink-0 rounded-full bg-amber-400/15 text-amber-300"><ExclamationTriangleIcon className="m-1.5 h-5 w-5" /></span><div><div className="text-sm font-bold text-white">{a.title}</div><p className="mt-1 text-xs leading-5 text-slate-400">{a.text}</p></div></div></div>)}</div></Panel></div></>; }
function OrderTable({ state }: { state: State }) { return <div className="overflow-x-auto"><table className="data-table"><thead><tr><th>Pedido</th><th>Proveedor</th><th>Total</th><th>Pago</th><th>Recepción</th></tr></thead><tbody>{state.orders.map((o) => <tr key={o.id}><td className="font-bold text-white">{o.id}</td><td>{supplierName(state.suppliers, o.supplierId)}</td><td>{money(orderTotal(o))}</td><td><Badge value={paymentLabel(state, o.id)} /></td><td><Badge value={state.receptions.find((r) => r.orderId === o.id)?.arrivedAt ? 'Llegó' : 'Pendiente'} /></td></tr>)}</tbody></table></div>; }
function Orders({ state, onNavigate }: { state: State; onNavigate: (s: Section) => void }) { const [printOrderId, setPrintOrderId] = useState<string | null>(null); return <><Panel title="Pedidos" subtitle="Total comprado separado del total recibido y pagado" action={<button type="button" onClick={() => onNavigate('Nuevo pedido')} className="button-primary"><PlusIcon className="h-4 w-4" /> Nuevo</button>}>{state.orders.length ? <div className="overflow-x-auto"><table className="data-table"><thead><tr><th>Pedido</th><th>Proveedor</th><th>Entrega</th><th>Comprado</th><th>Recepción</th><th>Pago</th><th>Acciones</th></tr></thead><tbody>{state.orders.map((o) => <tr key={o.id}><td className="font-bold text-white">{o.id}<div className="text-xs font-normal text-slate-500">{o.lines.length} artículos · {o.responsible}</div></td><td>{supplierName(state.suppliers, o.supplierId)}</td><td>{dateEs(o.expectedDate)}</td><td>{money(orderTotal(o))}</td><td><Badge value={state.receptions.find((r) => r.orderId === o.id)?.arrivedAt ? 'Llegó' : o.status} /></td><td><Badge value={paymentLabel(state, o.id)} /></td><td><div className="flex flex-wrap gap-2"><button type="button" onClick={() => setPrintOrderId(o.id)} className="button-primary">Exportar PDF</button><button type="button" onClick={() => onNavigate('Recepcion')} className="button-secondary">Abrir recepción</button></div></td></tr>)}</tbody></table></div> : <EmptyState text="No hay pedidos registrados." />}</Panel><OrderPdf state={state} orderId={printOrderId} onClose={() => setPrintOrderId(null)} /></>; }
function NewOrder({ state, update, notify, onNavigate }: { state: State; update: Mutate; notify: (m: string) => void; onNavigate: (s: Section) => void }) { const activeUsers = state.users.filter((u) => u.active); const [supplierId, setSupplierId] = useState(state.suppliers[0]?.id || ''); const [productId, setProductId] = useState(state.products[0]?.id || ''); const [quantity, setQuantity] = useState(1); const [price, setPrice] = useState(1000); const [responsible, setResponsible] = useState(activeUsers[0]?.name || ''); const save = () => { if (!supplierId || !productId || quantity < 1 || !responsible) return notify('Completa proveedor, producto, cantidad y responsable'); const order: Order = { id: `PED-${1048 + state.orders.length + 1}`, supplierId, lines: [{ id: `ol-${Date.now()}`, productId, quantity, price }], expectedDate: today, notes: '', responsible, status: 'Preparado', createdAt: today }; update((current) => ({ ...current, orders: [...current.orders, order] })); notify('Pedido creado'); onNavigate('Pedidos'); }; return <Panel title="Nuevo pedido" subtitle="La orden queda separada de la recepción hasta su llegada"><div className="grid gap-4 md:grid-cols-5"><Field label="Proveedor"><select className="field w-full" value={supplierId} onChange={(e) => setSupplierId(e.target.value)}>{state.suppliers.filter((s) => s.active).map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}</select></Field><Field label="Producto"><select className="field w-full" value={productId} onChange={(e) => setProductId(e.target.value)}>{state.products.filter((p) => p.active).map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label="Cantidad"><input className="field w-full" type="number" min="1" value={quantity} onChange={(e) => setQuantity(Number(e.target.value))} /></Field><Field label="Precio unitario"><input className="field w-full" type="number" min="0" value={price} onChange={(e) => setPrice(Number(e.target.value))} /></Field><Field label="Responsable"><select className="field w-full" value={responsible} onChange={(e) => setResponsible(e.target.value)}>{activeUsers.map((u) => <option key={u.id}>{u.name}</option>)}</select></Field></div><button type="button" onClick={save} className="button-primary mt-5">Guardar pedido</button></Panel>; }

function receptionFor(state: State, order: Order): State['receptions'][number] { return state.receptions.find((x) => x.orderId === order.id) || { id: `REC-${order.id}`, orderId: order.id, createdAt: today, lines: order.lines.map((line) => ({ id: `rl-${line.id}`, orderLineId: line.id, status: 'pending' as ReceptionStatus, expected: line.quantity, received: 0, expiry: '', lot: '', note: '', controlExpiry: false })) }; }
function Reception({ state, update, notify }: { state: State; update: Mutate; notify: (m: string) => void }) {
  const pendingOrders = state.orders.filter((o) => o.status !== 'Recibido'); const supplierIds = Array.from(new Set(pendingOrders.map((o) => o.supplierId))); const [supplierId, setSupplierId] = useState(supplierIds[0] || state.suppliers[0]?.id || ''); const supplierOrders = pendingOrders.filter((o) => o.supplierId === supplierId); const [orderId, setOrderId] = useState(supplierOrders[0]?.id || ''); const order = state.orders.find((x) => x.id === orderId) || supplierOrders[0]; const [draft, setDraft] = useState(order ? receptionFor(state, order) : null); const activeUsers = useMemo(() => state.users.filter((u) => u.active), [state.users]); const [responsible, setResponsible] = useState(activeUsers[0]?.name || '');
  useEffect(() => { const next = pendingOrders.filter((o) => o.supplierId === supplierId); if (!next.some((o) => o.id === orderId)) setOrderId(next[0]?.id || ''); }, [supplierId, orderId, pendingOrders]);
  useEffect(() => { if (order) { setDraft(receptionFor(state, order)); setResponsible(state.receptions.find((r) => r.orderId === order.id)?.responsible || activeUsers[0]?.name || ''); } }, [activeUsers, order, orderId, state]);
  const save = (complete: boolean) => { if (!draft || !order) return; if (complete && draft.lines.some((line) => line.status === 'pending')) return notify('Resuelve cada línea antes de guardar la recepción completa'); const arrivedAt = complete ? (draft.arrivedAt || new Date().toISOString()) : draft.arrivedAt; update((current) => { const saved = { ...draft, responsible, arrivedAt }; const receptions = [...current.receptions.filter((r) => r.orderId !== order.id), saved]; const expiries = saved.lines.filter((line) => line.controlExpiry && line.expiry && line.lot).map((line) => { const ol = order.lines.find((x) => x.id === line.orderLineId); return ol ? { id: `${saved.id}-${line.id}`, supplierId: order.supplierId, productId: ol.productId, lot: line.lot, quantity: line.received, date: line.expiry, receptionId: saved.id } : null; }).filter((x): x is Expiry => Boolean(x)); return { ...current, receptions, expiries: [...current.expiries.filter((e) => e.receptionId !== saved.id), ...expiries], orders: complete ? current.orders.map((o) => o.id === order.id ? { ...o, status: 'Recibido' as const } : o) : current.orders }; }); notify(complete ? 'Recepción completa guardada' : 'Estado de línea guardado'); };
  const setLine = (lineId: string, patch: Partial<ReceptionLine>) => setDraft((current) => current ? { ...current, lines: current.lines.map((line) => line.id === lineId ? { ...line, ...patch } : line) } : current);
  if (!pendingOrders.length) return <Panel title="Recepción" subtitle="Entrada de mercadería"><EmptyState text="No hay pedidos pendientes por recibir." /></Panel>;
  return <><Panel title="Recepción por proveedor" subtitle="Selecciona primero el proveedor, luego el pedido pendiente"><div className="grid gap-4 lg:grid-cols-2"><Field label="Proveedor con pedidos por recibir"><select className="field w-full" value={supplierId} onChange={(e) => { setSupplierId(e.target.value); setOrderId(''); }}>{supplierIds.map((id) => <option key={id} value={id}>{supplierName(state.suppliers, id)} · {pendingOrders.filter((o) => o.supplierId === id).length} pedido(s)</option>)}</select></Field><Field label="Pedido"><select className="field w-full" value={order?.id || ''} onChange={(e) => setOrderId(e.target.value)}>{supplierOrders.map((o) => <option key={o.id} value={o.id}>{o.id} · {dateEs(o.expectedDate)} · {money(orderTotal(o))}</option>)}</select></Field></div><div className="mt-4 grid gap-3 sm:grid-cols-3">{supplierIds.map((id) => { const orders = pendingOrders.filter((o) => o.supplierId === id); return <div key={id} className="rounded-xl border border-white/10 p-3"><div className="font-bold text-white">{supplierName(state.suppliers, id)}</div><div className="mt-1 text-xs text-slate-400">{orders.length} pedido(s) · {orders.reduce((sum, o) => sum + orderTotal(o), 0).toLocaleString('es-CO')} total</div></div>; })}</div></Panel>{order && draft && <Panel title={`Líneas de ${order.id}`} subtitle={`${supplierName(state.suppliers, order.supplierId)} · cada cambio queda en borrador hasta guardar`} action={<Field label="Responsable"><select className="field" value={responsible} onChange={(e) => setResponsible(e.target.value)}>{activeUsers.map((u) => <option key={u.id}>{u.name}</option>)}</select></Field>}><div className="space-y-4">{draft.lines.map((line) => { const ol = order.lines.find((x) => x.id === line.orderLineId); const product = state.products.find((p) => p.id === ol?.productId); return <div key={line.id} className="rounded-xl border border-white/10 p-4"><div className="mb-3 flex flex-wrap items-center justify-between gap-2"><div><div className="font-bold text-white">{product?.name || 'Producto eliminado'}</div><div className="text-xs text-slate-400">Esperada: {line.expected} · Recibida: {line.received} · Diferencia: {line.received - line.expected}</div></div><Badge value={receptionLabels[line.status]} /></div><div className="grid gap-3 md:grid-cols-5"><Field label="Estado"><select className="field w-full" value={line.status} onChange={(e) => setLine(line.id, { status: e.target.value as ReceptionStatus })}>{Object.entries(receptionLabels).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></Field><Field label="Cantidad recibida"><input className="field w-full" type="number" min="0" value={line.received} onChange={(e) => setLine(line.id, { received: Number(e.target.value) })} /></Field><Field label="Lote opcional"><input className="field w-full" value={line.lot} onChange={(e) => setLine(line.id, { lot: e.target.value })} /></Field><Field label="Nota"><input className="field w-full" value={line.note} onChange={(e) => setLine(line.id, { note: e.target.value })} /></Field><Field label="Controlar vencimiento"><label className="flex min-h-10 items-center gap-2 rounded-lg border border-white/15 bg-[#102a35] px-3 text-xs"><input type="checkbox" checked={Boolean(line.controlExpiry)} onChange={(e) => setLine(line.id, { controlExpiry: e.target.checked })} /> Sí</label></Field></div>{line.controlExpiry && <div className="mt-3 max-w-xs"><Field label="Fecha de vencimiento"><input className="field w-full" type="date" value={line.expiry} onChange={(e) => setLine(line.id, { expiry: e.target.value })} /></Field></div>}<button type="button" className="button-secondary mt-3" onClick={() => save(false)}>Guardar estado</button></div>; })}</div><div className="mt-5 flex flex-wrap gap-2"><button type="button" className="button-primary" onClick={() => save(true)}>Guardar recepción completa</button><span className="self-center text-xs text-slate-400">Llegada: {draft.arrivedAt ? new Date(draft.arrivedAt).toLocaleString('es-ES') : 'aún no registrada'}</span></div></Panel>}</>;
}
function Arrivals({ state, onNavigate }: { state: State; onNavigate: (s: Section) => void }) { const rows = state.receptions.map((r) => ({ r, order: state.orders.find((o) => o.id === r.orderId) })).filter((x) => x.order); return <Panel title="Proveedores llegados" subtitle="Recepciones por fecha, hora, pedido, estado y diferencias">{rows.length ? <div className="overflow-x-auto"><table className="data-table"><thead><tr><th>Fecha / hora</th><th>Proveedor</th><th>Pedido</th><th>Estado</th><th>Recibido</th><th>Diferencias</th><th /></tr></thead><tbody>{rows.map(({ r, order }) => { const received = r.lines.reduce((sum, l) => sum + l.received, 0); const differences = r.lines.filter((l) => l.status !== 'received').length; return <tr key={r.id}><td>{r.arrivedAt ? `${dateEs(r.arrivedAt)} · ${r.arrivedAt.slice(11, 16)}` : `${dateEs(r.createdAt)} · Pendiente`}</td><td className="font-semibold text-white">{supplierName(state.suppliers, order!.supplierId)}</td><td>{order!.id}</td><td><Badge value={r.arrivedAt ? 'Llegó' : 'Pendiente'} /></td><td>{received} uds.</td><td>{differences ? <Badge value={`${differences} diferencia(s)`} /> : 'Sin diferencias'}</td><td><button type="button" onClick={() => onNavigate('Recepcion')} className="button-secondary">Abrir</button></td></tr>; })}</tbody></table></div> : <EmptyState text="Todavía no hay recepciones guardadas." />}</Panel>; }
function Suppliers({ state, update, notify }: { state: State; update: Mutate; notify: (m: string) => void }) {
  const [query, setQuery] = useState('');
  const [editing, setEditing] = useState<Supplier | null>(null);
  const paymentOptions = ['efectivo', 'transferencia', 'cuenta corriente', 'tarjeta', 'Otro'];
  const filtered = state.suppliers.filter((x) => `${x.name} ${x.contact} ${x.active ? 'activo' : 'inactivo'}`.toLowerCase().includes(query.toLowerCase()));
  const add = () => { const name = window.prompt('Nombre del proveedor'); if (!name?.trim()) return; update((current) => ({ ...current, suppliers: [...current.suppliers, { id: `sup-${Date.now()}`, name: name.trim(), contact: '', phone: '', email: '', address: '', terms: 'efectivo', notes: '', active: true }] })); notify('Proveedor creado'); };
  const open = (supplier: Supplier) => setEditing({ ...supplier });
  const save = () => {
    if (!editing?.name.trim()) return notify('El nombre del proveedor es obligatorio');
    if (editing.email && !/^\S+@\S+\.\S+$/.test(editing.email)) return notify('Ingresa un email válido');
    if (!editing.terms.trim()) return notify('Selecciona o escribe una preferencia de pago');
    const saved = { ...editing, name: editing.name.trim(), contact: editing.contact.trim(), email: editing.email.trim(), terms: editing.terms.trim() };
    update((current) => ({ ...current, suppliers: current.suppliers.map((item) => item.id === saved.id ? saved : item) }));
    setEditing(null);
    notify('Proveedor actualizado');
  };
  const remove = (supplier: Supplier) => { const dependencies = [state.orders.some((x) => x.supplierId === supplier.id) && 'pedidos', state.receptions.some((x) => state.orders.some((order) => order.id === x.orderId && order.supplierId === supplier.id)) && 'recepciones', state.payments.some((x) => x.supplierId === supplier.id) && 'pagos', state.sources.some((x) => x.supplierId === supplier.id) && 'fuentes', state.supplierProducts.some((x) => x.supplierId === supplier.id) && 'relaciones de catálogo'].filter(Boolean) as string[]; if (dependencies.length) { if (window.confirm(`No se puede eliminar ${supplier.name} porque conserva ${dependencies.join(', ')}. ¿Desactivar proveedor?`)) { update((current) => ({ ...current, suppliers: current.suppliers.map((item) => item.id === supplier.id ? { ...item, active: false } : item) })); notify('Proveedor desactivado; su historial se conserva y no aparecerá en nuevos pedidos.'); } return; } if (window.confirm(`¿Eliminar definitivamente a ${supplier.name}? Esta acción elimina el dato demo sin historial asociado.`)) { update((current) => ({ ...current, suppliers: current.suppliers.filter((item) => item.id !== supplier.id), supplierProducts: current.supplierProducts.filter((item) => item.supplierId !== supplier.id) })); notify('Proveedor eliminado'); } };
  return <><Panel title="Proveedores" subtitle="Directorio y saldo de pagos; los proveedores con historial se desactivan para conservar trazabilidad." action={<div className="flex flex-wrap gap-2"><input aria-label="Buscar proveedores" className="field w-48" placeholder="Buscar..." value={query} onChange={(e) => setQuery(e.target.value)} /><button type="button" onClick={add} className="button-primary"><PlusIcon className="h-4 w-4" /> Nuevo</button></div>}><div className="overflow-x-auto"><table className="data-table"><thead><tr><th>Proveedor</th><th>Contacto</th><th>Preferencia de pago</th><th>Estado</th><th>Pagado</th><th>Pendiente</th><th>Acción</th></tr></thead><tbody>{filtered.map((s) => { const paid = state.payments.filter((p) => p.supplierId === s.id && !p.cancelled && p.status === 'pagado').reduce((a, p) => a + p.amount, 0); const due = state.payments.filter((p) => p.supplierId === s.id && !p.cancelled && p.status !== 'pagado').reduce((a, p) => a + p.amount, 0); return <tr key={s.id}><td className="font-bold text-white">{s.name}</td><td>{s.contact || 'Sin contacto'}</td><td>{s.terms || 'Sin definir'}</td><td><Badge value={s.active ? 'Activo' : 'Desactivado'} /></td><td className="text-emerald-300">{money(paid)}</td><td className="text-amber-300">{money(due)}</td><td><div className="flex flex-wrap gap-2"><button type="button" className="button-secondary" onClick={() => open(s)}>Editar</button><button type="button" className="button-danger" onClick={() => remove(s)}>{s.active ? 'Eliminar' : 'Eliminar / revisar'}</button></div></td></tr>; })}</tbody></table></div></Panel>{editing && <Panel title={`Editar proveedor: ${editing.name || 'Nuevo'}`} subtitle="Los cambios se guardan solo al confirmar. Cancelar descarta este borrador."><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><Field label="Nombre *"><input className="field w-full" autoFocus value={editing.name} onChange={(e) => setEditing({ ...editing, name: e.target.value })} /></Field><Field label="Contacto"><input className="field w-full" value={editing.contact} onChange={(e) => setEditing({ ...editing, contact: e.target.value })} /></Field><Field label="Teléfono"><input className="field w-full" type="tel" value={editing.phone} onChange={(e) => setEditing({ ...editing, phone: e.target.value })} /></Field><Field label="Email"><input className="field w-full" type="email" value={editing.email} onChange={(e) => setEditing({ ...editing, email: e.target.value })} /></Field><Field label="Dirección"><input className="field w-full" value={editing.address} onChange={(e) => setEditing({ ...editing, address: e.target.value })} /></Field><Field label="Preferencia de pago"><select className="field w-full" value={paymentOptions.includes(editing.terms) ? editing.terms : 'Otro'} onChange={(e) => setEditing({ ...editing, terms: e.target.value === 'Otro' ? '' : e.target.value })}><option value="">Selecciona una opción</option>{paymentOptions.map((option) => <option key={option} value={option}>{option}</option>)}</select></Field>{(!paymentOptions.includes(editing.terms) || editing.terms === '') && <Field label="Otra preferencia *"><input className="field w-full" value={editing.terms} placeholder="Ej. 30 días" onChange={(e) => setEditing({ ...editing, terms: e.target.value })} /></Field>}<Field label="Notas"><textarea className="field min-h-24 w-full" value={editing.notes} onChange={(e) => setEditing({ ...editing, notes: e.target.value })} /></Field></div><div className="mt-5 flex flex-wrap justify-end gap-2"><button type="button" className="button-secondary" onClick={() => setEditing(null)}>Cancelar</button><button type="button" className="button-primary" onClick={save}>Guardar cambios</button></div></Panel>}</>;
}

function Catalog({ state, update, notify }: { state: State; update: Mutate; notify: (m: string) => void }) { const [query, setQuery] = useState(''); const [editing, setEditing] = useState<Product | null>(null); const [supplierId, setSupplierId] = useState(state.suppliers[0]?.id || ''); const [price, setPrice] = useState(0); const filtered = state.products.filter((p) => `${p.name} ${p.sku} ${p.category} ${p.brand || ''}`.toLowerCase().includes(query.toLowerCase())); const open = (product: Product) => { setEditing({ ...product }); const link = state.supplierProducts.find((x) => x.productId === product.id); setSupplierId(link?.supplierId || state.suppliers[0]?.id || ''); setPrice(link?.price || 0); }; const save = () => { if (!editing?.name.trim() || !editing.sku.trim()) return notify('Completa nombre y SKU'); const link: SupplierProduct = { id: state.supplierProducts.find((x) => x.productId === editing.id && x.supplierId === supplierId)?.id || `sp-${Date.now()}`, supplierId, productId: editing.id, price, externalCode: editing.sku, presentation: editing.unit, active: editing.active }; update((current) => ({ ...current, products: current.products.some((x) => x.id === editing.id) ? current.products.map((x) => x.id === editing.id ? editing : x) : [...current.products, editing], supplierProducts: supplierId ? [...current.supplierProducts.filter((x) => !(x.productId === editing.id && x.supplierId === supplierId)), link] : current.supplierProducts })); setEditing(null); notify('Producto guardado'); }; const newProduct = () => { setEditing({ id: `prod-${Date.now()}`, name: '', sku: '', category: '', unit: '', stock: 0, minimum: 0, active: true }); setSupplierId(state.suppliers[0]?.id || ''); setPrice(0); }; return <><Panel title="Catálogo" subtitle="Productos, marcas, presentaciones, precios y procedencia" action={<div className="flex flex-wrap gap-2"><input aria-label="Buscar productos" className="field w-52" placeholder="Buscar nombre, SKU..." value={query} onChange={(e) => setQuery(e.target.value)} /><button type="button" onClick={newProduct} className="button-primary"><PlusIcon className="h-4 w-4" /> Nuevo producto</button></div>}>{filtered.length ? <div className="overflow-x-auto"><table className="data-table"><thead><tr><th>Producto / SKU</th><th>Marca / categoría</th><th>Presentación</th><th>Stock</th><th>Proveedor</th><th>Precio</th><th>Estado</th><th /></tr></thead><tbody>{filtered.map((p) => { const link = state.supplierProducts.find((x) => x.productId === p.id); return <tr key={p.id}><td className="font-bold text-white">{p.name}<div className="text-xs font-normal text-slate-500">{p.sku}</div></td><td>{p.brand || 'Sin marca'}<div className="text-xs">{p.category || 'Sin categoría'}</div></td><td>{p.unit || 'Sin presentación'}</td><td>{p.stock} / mín. {p.minimum}</td><td>{link ? supplierName(state.suppliers, link.supplierId) : 'Sin proveedor'}</td><td>{link ? money(link.price) : '—'}</td><td><Badge value={p.active ? 'Activo' : 'Inactivo'} /></td><td><button type="button" className="button-secondary" onClick={() => open(p)}>Detalle / editar</button></td></tr>; })}</tbody></table></div> : <EmptyState text="No hay productos que coincidan." />}</Panel>{editing && <Panel title={state.products.some((x) => x.id === editing.id) ? 'Editar producto' : 'Alta de producto'} subtitle="Los cambios se conservan en este navegador"><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><Field label="Nombre"><input className="field w-full" value={editing.name} onChange={(e) => setEditing({ ...editing, name: e.target.value })} /></Field><Field label="SKU"><input className="field w-full" value={editing.sku} onChange={(e) => setEditing({ ...editing, sku: e.target.value })} /></Field><Field label="Marca"><input className="field w-full" value={editing.brand || ''} onChange={(e) => setEditing({ ...editing, brand: e.target.value })} /></Field><Field label="Categoría"><input className="field w-full" value={editing.category} onChange={(e) => setEditing({ ...editing, category: e.target.value })} /></Field><Field label="Presentación / unidad"><input className="field w-full" value={editing.unit} onChange={(e) => setEditing({ ...editing, unit: e.target.value })} /></Field><Field label="Stock"><input className="field w-full" type="number" min="0" value={editing.stock} onChange={(e) => setEditing({ ...editing, stock: Number(e.target.value) })} /></Field><Field label="Mínimo"><input className="field w-full" type="number" min="0" value={editing.minimum} onChange={(e) => setEditing({ ...editing, minimum: Number(e.target.value) })} /></Field><Field label="Proveedor"><select className="field w-full" value={supplierId} onChange={(e) => setSupplierId(e.target.value)}>{state.suppliers.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}</select></Field><Field label="Precio"><input className="field w-full" type="number" min="0" value={price} onChange={(e) => setPrice(Number(e.target.value))} /></Field></div><div className="mt-5 flex gap-2"><button type="button" className="button-primary" onClick={save}>Guardar producto</button><button type="button" className="button-secondary" onClick={() => setEditing(null)}>Cancelar</button></div></Panel>}</>; }

function parseCandidates(text: string, sourceId: string): SourceCandidate[] { const rows = text.split(/\r?\n/).map((line) => line.trim()).filter(Boolean); const candidates: SourceCandidate[] = []; rows.forEach((row, index) => { const sku = row.match(/\b[A-Z]{2,}[\-_][A-Z0-9\-_]+\b|\b[A-Z]{2,}\d{2,}\b/)?.[0] || ''; const priceMatch = row.match(/(?:\$|USD|ARS|EUR)\s?([\d.,]+)/i); if (sku || priceMatch) { const price = priceMatch ? Number(priceMatch[1].replace(/\./g, '').replace(',', '.')) || 0 : 0; candidates.push({ id: `${sourceId}-cand-${index}`, name: row.replace(sku, '').replace(priceMatch?.[0] || '', '').trim() || `Candidato ${index + 1}`, sku, brand: '', unit: '', category: '', price, currency: priceMatch?.[0].toUpperCase().includes('USD') ? 'USD' : 'ARS', availability: '', expiry: '', status: 'Pendiente', notes: 'Detectado desde texto; revisar antes de confirmar.' }); } }); return candidates.slice(0, 100); }
function safeSourceUrl(value: string) { try { const parsed = new URL(value); return parsed.protocol === 'http:' || parsed.protocol === 'https:'; } catch { return false; } }
function Sources({ state, update, notify }: { state: State; update: Mutate; notify: (m: string) => void }) {
  const [supplierId, setSupplierId] = useState(state.suppliers[0]?.id || ''); const [kind, setKind] = useState<'PDF' | 'URL'>('URL'); const [name, setName] = useState(''); const [url, setUrl] = useState(''); const [file, setFile] = useState<File | null>(null); const [files, setFiles] = useState<Record<string, File>>({}); const [selected, setSelected] = useState<string | null>(state.sources[0]?.id || null); const source = state.sources.find((s) => s.id === selected); const statuses: ReviewStatus[] = ['Pendiente', 'Revisado', 'Confirmado', 'Rechazado']; const maxPdf = 10 * 1024 * 1024;
  const add = () => { if (!supplierId || !name.trim() || (kind === 'URL' && !url.trim()) || (kind === 'PDF' && !file)) return notify('Completa proveedor, nombre y la fuente'); if (kind === 'URL' && !safeSourceUrl(url)) return notify('La URL debe ser pública y comenzar con http:// o https://'); if (kind === 'PDF' && file && (file.type !== 'application/pdf' && !file.name.toLowerCase().endsWith('.pdf'))) return notify('Solo se permiten archivos PDF'); if (kind === 'PDF' && file && file.size > maxPdf) return notify('El PDF supera el máximo de 10 MB'); const newSource: Source = { id: `src-${Date.now()}`, supplierId, kind, name: name.trim(), url: kind === 'URL' ? url.trim() : undefined, fileName: file?.name, size: file?.size, contentType: file?.type, date: today, status: 'Pendiente', notes: '', provenance: kind === 'URL' ? `URL pública declarada: ${url.trim()}` : `Archivo local subido: ${file?.name}`, extractionStatus: 'Pendiente', candidates: [] }; update((current) => ({ ...current, sources: [...current.sources, newSource] })); if (file) setFiles((current) => ({ ...current, [newSource.id]: file })); setSelected(newSource.id); setName(''); setUrl(''); setFile(null); notify('Fuente registrada; inicia la revisión para extraer candidatos'); };
  const review = async (item: Source) => { update((current) => ({ ...current, sources: current.sources.map((s) => s.id === item.id ? { ...s, extractionStatus: 'Pendiente', extractionError: undefined } : s) })); try { let text = ''; if (item.kind === 'PDF') { notify('Leyendo texto embebido del PDF; no es OCR'); const currentFile = files[item.id]; if (!currentFile) throw new Error('El archivo PDF no queda disponible tras recargar; vuelva a subirlo para revisar.'); text = await currentFile.text(); } else { const response = await fetch('/api/source-preview', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ url: item.url }) }); const payload = await response.json() as { text?: string; error?: string }; if (!response.ok) throw new Error(payload.error || 'No se pudo leer la URL'); text = payload.text || ''; } const candidates = parseCandidates(text, item.id); update((current) => ({ ...current, sources: current.sources.map((s) => s.id === item.id ? { ...s, extractionStatus: candidates.length ? 'Extraído' : 'Revisión manual', extractedAt: new Date().toISOString(), candidates, notes: candidates.length ? 'Candidatos detectados, pendientes de edición y confirmación.' : 'No se detectaron filas estructuradas; agregar candidatos manualmente.' } : s) })); notify(candidates.length ? `${candidates.length} candidato(s) detectado(s)` : 'No se detectaron candidatos; la revisión manual queda habilitada'); } catch (error) { const message = error instanceof Error ? error.message : 'Error desconocido'; update((current) => ({ ...current, sources: current.sources.map((s) => s.id === item.id ? { ...s, extractionStatus: 'Error', extractionError: message } : s) })); notify(`No se pudo extraer: ${message}`); } };
  const editCandidate = (candidate: SourceCandidate, patch: Partial<SourceCandidate>) => source && update((current) => ({ ...current, sources: current.sources.map((s) => s.id === source.id ? { ...s, candidates: s.candidates.map((c) => c.id === candidate.id ? { ...c, ...patch } : c) } : s) }));
  const addCandidate = () => source && update((current) => ({ ...current, sources: current.sources.map((s) => s.id === source.id ? { ...s, candidates: [...s.candidates, { id: `${s.id}-manual-${Date.now()}`, name: '', sku: '', brand: '', unit: '', category: '', price: 0, currency: 'ARS', availability: '', expiry: '', status: 'Pendiente', notes: 'Agregado manualmente' }] } : s) }));
  const confirmCandidates = () => { if (!source) return; const approved = source.candidates.filter((c) => c.status === 'Aprobado' && c.name.trim()); if (!approved.length) return notify('Edita y marca como Aprobado al menos un candidato'); update((current) => { let products = [...current.products]; let supplierProducts = [...current.supplierProducts]; approved.forEach((c) => { const existing = products.find((p) => (c.sku && p.sku.toLowerCase() === c.sku.toLowerCase()) || p.name.toLowerCase() === c.name.toLowerCase()); const product: Product = existing ? { ...existing, brand: c.brand || existing.brand, unit: c.unit || existing.unit, category: c.category || existing.category, currency: c.currency, availability: c.availability, expiry: c.expiry, sourceId: source.id } : { id: `prod-${Date.now()}-${c.id}`, name: c.name, sku: c.sku || `SRC-${c.id}`, brand: c.brand, unit: c.unit, category: c.category, stock: 0, minimum: 0, active: true, currency: c.currency, availability: c.availability, expiry: c.expiry, sourceId: source.id }; if (existing) products = products.map((p) => p.id === existing.id ? product : p); else products.push(product); supplierProducts = [...supplierProducts.filter((x) => !(x.productId === product.id && x.supplierId === source.supplierId)), { id: `sp-${source.id}-${c.id}`, supplierId: source.supplierId, productId: product.id, price: c.price, externalCode: c.sku, presentation: c.unit, active: true }]; }); return { ...current, products, supplierProducts, sources: current.sources.map((s) => s.id === source.id ? { ...s, status: 'Confirmado', candidates: s.candidates.map((c) => approved.some((a) => a.id === c.id) ? { ...c, status: 'Aprobado' as CandidateStatus } : c) } : s) }; }); notify(`${approved.length} candidato(s) importado(s); duplicados por SKU/nombre actualizados`); };
  const remove = (id: string) => { if (!window.confirm('¿Eliminar esta fuente?')) return; update((current) => ({ ...current, sources: current.sources.filter((s) => s.id !== id) })); if (selected === id) setSelected(null); notify('Fuente eliminada'); };
  return <><Panel title="Fuentes de catálogos" subtitle="Asocia PDF o URL a un proveedor. La extracción siempre requiere revisión humana."><div className="grid gap-3 md:grid-cols-5"><Field label="Proveedor"><select className="field w-full" value={supplierId} onChange={(e) => setSupplierId(e.target.value)}>{state.suppliers.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}</select></Field><Field label="Tipo"><select className="field w-full" value={kind} onChange={(e) => setKind(e.target.value as 'PDF' | 'URL')}><option value="URL">URL pública</option><option value="PDF">PDF</option></select></Field><Field label="Nombre"><input className="field w-full" value={name} onChange={(e) => setName(e.target.value)} placeholder="Catálogo septiembre" /></Field>{kind === 'URL' ? <Field label="URL"><input className="field w-full" type="url" value={url} onChange={(e) => setUrl(e.target.value)} placeholder="https://..." /></Field> : <Field label="Archivo PDF"><input className="field w-full" type="file" accept="application/pdf,.pdf" onChange={(e) => setFile(e.target.files?.[0] || null)} /><span className="mt-1 block text-[10px] text-slate-500">Máximo 10 MB. No OCR productivo.</span></Field>}<div className="flex items-end"><button type="button" className="button-primary w-full" onClick={add}>Registrar fuente</button></div></div><p className="mt-4 text-xs text-slate-500">Las URL se leen solo vía servidor con http/https público; se bloquean localhost, IPs privadas, file://, javascript: y cuerpos mayores a 5 MB.</p></Panel><Panel title="Cola de revisión" subtitle={`${state.sources.length} fuente(s) · procedencia, metadata y estado persistidos`}>{state.sources.length ? <div className="overflow-x-auto"><table className="data-table"><thead><tr><th>Fuente / procedencia</th><th>Proveedor</th><th>Tipo / tamaño</th><th>Extracción</th><th>Revisión</th><th /></tr></thead><tbody>{state.sources.map((s) => <tr key={s.id}><td className="font-bold text-white">{s.name}<div className="max-w-xs truncate text-xs font-normal text-slate-500">{s.url || s.fileName || 'Sin referencia'}</div></td><td>{supplierName(state.suppliers, s.supplierId)}</td><td>{s.kind}{s.size ? ` · ${(s.size / 1024).toFixed(1)} KB` : ''}</td><td><Badge value={s.extractionStatus} />{s.extractionError && <div className="mt-1 max-w-xs text-xs text-red-300">{s.extractionError}</div>}</td><td><select aria-label={`Estado de ${s.name}`} className="field" value={s.status} onChange={(e) => update((current) => ({ ...current, sources: current.sources.map((x) => x.id === s.id ? { ...x, status: e.target.value as ReviewStatus } : x) }))}>{statuses.map((x) => <option key={x}>{x}</option>)}</select></td><td className="space-x-2"><button type="button" className="button-secondary" onClick={() => { setSelected(s.id); void review(s); }}>Revisar / extraer</button><button type="button" className="icon-button" aria-label={`Eliminar ${s.name}`} onClick={() => remove(s.id)}><TrashIcon className="h-4 w-4" /></button></td></tr>)}</tbody></table></div> : <EmptyState text="Registra una fuente para iniciar revisión." />}</Panel>{source && <Panel title={`Candidatos de ${source.name}`} subtitle="Edita cada campo, rechaza los que no correspondan y aprueba solo los válidos" action={<div className="flex gap-2"><button type="button" className="button-secondary" onClick={addCandidate}>Agregar candidato manual</button><button type="button" className="button-primary" onClick={confirmCandidates}>Confirmar aprobados</button></div>}>{source.extractionStatus === 'Error' && <p className="mb-4 rounded-lg border border-red-300/20 bg-red-400/10 p-3 text-xs text-red-200">{source.extractionError} La aplicación no inventa datos: corrige manualmente o vuelve a intentar.</p>}{source.candidates.length ? <div className="space-y-3">{source.candidates.map((c) => <div key={c.id} className="grid gap-2 rounded-xl border border-white/10 p-3 md:grid-cols-7"><input aria-label="Nombre candidato" className="field" value={c.name} onChange={(e) => editCandidate(c, { name: e.target.value })} placeholder="Nombre" /><input aria-label="SKU candidato" className="field" value={c.sku} onChange={(e) => editCandidate(c, { sku: e.target.value })} placeholder="SKU" /><input aria-label="Marca candidato" className="field" value={c.brand} onChange={(e) => editCandidate(c, { brand: e.target.value })} placeholder="Marca" /><input aria-label="Unidad candidato" className="field" value={c.unit} onChange={(e) => editCandidate(c, { unit: e.target.value })} placeholder="Unidad" /><input aria-label="Categoría candidato" className="field" value={c.category} onChange={(e) => editCandidate(c, { category: e.target.value })} placeholder="Categoría" /><input aria-label="Precio candidato" className="field" type="number" value={c.price} onChange={(e) => editCandidate(c, { price: Number(e.target.value) })} /><select aria-label="Estado candidato" className="field" value={c.status} onChange={(e) => editCandidate(c, { status: e.target.value as CandidateStatus })}><option>Pendiente</option><option>Aprobado</option><option>Rechazado</option></select></div>)}</div> : <EmptyState text="No hay candidatos. Usa revisión manual para agregarlos." />}</Panel>}</>;
}

function Expiries({ state, update, notify }: { state: State; update: Mutate; notify: (m: string) => void }) { const [filter, setFilter] = useState<'all' | 'soon' | 'expired'>('all'); const [editing, setEditing] = useState<Expiry | null>(null); const days = (date: string) => Math.ceil((new Date(`${date}T00:00:00`).getTime() - new Date(`${today}T00:00:00`).getTime()) / 86400000); const filtered = state.expiries.filter((x) => filter === 'all' || (filter === 'soon' ? days(x.date) >= 0 && days(x.date) <= 3 : days(x.date) < 0)); const save = () => { if (!editing?.date || !editing.lot.trim()) return notify('Completa fecha y lote'); update((current) => ({ ...current, expiries: current.expiries.map((x) => x.id === editing.id ? editing : x) })); setEditing(null); notify('Vencimiento actualizado'); }; return <><Panel title="Vencimientos" subtitle="Lotes recibidos con control de fecha y alerta operativa" action={<select aria-label="Filtrar vencimientos" className="field" value={filter} onChange={(e) => setFilter(e.target.value as typeof filter)}><option value="all">Todos</option><option value="soon">Próximos 3 días</option><option value="expired">Vencidos</option></select>}>{filtered.length ? <div className="overflow-x-auto"><table className="data-table"><thead><tr><th>Producto</th><th>Proveedor</th><th>Lote</th><th>Fecha</th><th>Cantidad</th><th>Estado</th><th /></tr></thead><tbody>{filtered.map((x) => { const remaining = days(x.date); return <tr key={x.id}><td className="font-bold text-white">{state.products.find((p) => p.id === x.productId)?.name || 'Producto eliminado'}</td><td>{supplierName(state.suppliers, x.supplierId)}</td><td>{x.lot}</td><td>{dateEs(x.date)}</td><td>{x.quantity}</td><td><Badge value={remaining < 0 ? 'Vencido' : remaining <= 3 ? `Alerta ${remaining} día(s)` : 'Vigente'} /></td><td><button type="button" className="button-secondary" onClick={() => setEditing({ ...x })}>Editar lote / fecha</button></td></tr>; })}</tbody></table></div> : <EmptyState text="No hay vencimientos para este filtro. Activa control en una recepción." />}</Panel>{editing && <Panel title="Editar vencimiento" subtitle="Actualiza lote y fecha de la recepción"><div className="grid gap-4 sm:grid-cols-3"><Field label="Producto"><input className="field w-full" value={state.products.find((p) => p.id === editing.productId)?.name || ''} readOnly /></Field><Field label="Lote"><input className="field w-full" value={editing.lot} onChange={(e) => setEditing({ ...editing, lot: e.target.value })} /></Field><Field label="Fecha"><input className="field w-full" type="date" value={editing.date} onChange={(e) => setEditing({ ...editing, date: e.target.value })} /></Field></div><button type="button" className="button-primary mt-5" onClick={save}>Guardar vencimiento</button></Panel>}</>; }
function Users({ state, update, notify }: { state: State; update: Mutate; notify: (m: string) => void }) { const [editing, setEditing] = useState<User | null>(null); const active = state.users.filter((u) => u.active).length; const save = () => { if (!editing?.name.trim()) return notify('El nombre es obligatorio'); if (editing.active === false && state.users.find((u) => u.id === editing.id)?.active && active <= 1) return notify('No puedes dejar el sistema sin usuarios activos'); update((current) => ({ ...current, users: current.users.some((u) => u.id === editing.id) ? current.users.map((u) => u.id === editing.id ? editing : u) : [...current.users, editing] })); setEditing(null); notify('Usuario guardado'); }; const remove = (user: User) => { if (active === 1 && user.active) return notify('No puedes eliminar el último usuario activo'); if (window.confirm(`¿Eliminar a ${user.name}?`)) update((current) => ({ ...current, users: current.users.filter((u) => u.id !== user.id) })); }; return <><Panel title="Usuarios y administración" subtitle="Roles demo visibles; la autorización servidor real queda para una API futura" action={<button type="button" className="button-primary" onClick={() => setEditing({ id: `usr-${Date.now()}`, name: '', email: '', role: 'Consulta', active: true, createdAt: today })}><PlusIcon className="h-4 w-4" /> Nuevo usuario</button>}><div className="mb-5 grid gap-3 sm:grid-cols-4">{roles.map((role) => <div key={role} className="rounded-xl border border-white/10 p-3"><div className="font-bold text-white">{role}</div><div className="mt-1 text-xs text-slate-400">{role === 'Administrador' ? 'Gestiona usuarios y configuración' : role === 'Compras' ? 'Pedidos y proveedores' : role === 'Recepción' ? 'Recepciones y vencimientos' : 'Consulta de información'}</div></div>)}</div><div className="overflow-x-auto"><table className="data-table"><thead><tr><th>Nombre</th><th>Email</th><th>Rol / permisos demo</th><th>Alta</th><th>Estado</th><th /></tr></thead><tbody>{state.users.map((u) => <tr key={u.id}><td className="font-bold text-white">{u.name}</td><td>{u.email || 'No informado'}</td><td>{u.role}</td><td>{dateEs(u.createdAt)}</td><td><button type="button" onClick={() => { if (u.active && active <= 1) return notify('No puedes dejar el sistema sin usuarios activos'); update((current) => ({ ...current, users: current.users.map((x) => x.id === u.id ? { ...x, active: !x.active } : x) })); }}><Badge value={u.active ? 'Activo' : 'Inactivo'} /></button></td><td className="space-x-2"><button type="button" className="button-secondary" onClick={() => setEditing({ ...u })}>Editar</button><button type="button" className="icon-button" aria-label={`Eliminar ${u.name}`} onClick={() => remove(u)}><TrashIcon className="h-4 w-4" /></button></td></tr>)}</tbody></table></div></Panel>{editing && <Panel title="Editar usuario" subtitle="El email es opcional; no se inventan datos"><div className="grid gap-4 sm:grid-cols-4"><Field label="Nombre"><input className="field w-full" value={editing.name} onChange={(e) => setEditing({ ...editing, name: e.target.value })} /></Field><Field label="Email opcional"><input className="field w-full" type="email" value={editing.email || ''} onChange={(e) => setEditing({ ...editing, email: e.target.value })} /></Field><Field label="Rol"><select className="field w-full" value={editing.role} onChange={(e) => setEditing({ ...editing, role: e.target.value as UserRole })}>{roles.map((role) => <option key={role}>{role}</option>)}</select></Field><Field label="Activo"><input type="checkbox" checked={editing.active} onChange={(e) => setEditing({ ...editing, active: e.target.checked })} /></Field></div><div className="mt-5 flex gap-2"><button type="button" className="button-primary" onClick={save}>Guardar usuario</button><button type="button" className="button-secondary" onClick={() => setEditing(null)}>Cancelar</button></div></Panel>}</>; }
function Payments({ state, update, notify, exportCsv }: { state: State; update: Mutate; notify: (m: string) => void; exportCsv: () => void }) { const [supplier, setSupplier] = useState(''); const [status, setStatus] = useState(''); const [editing, setEditing] = useState<Payment | null>(null); const users = state.users.filter((u) => u.active); const filtered = state.payments.filter((p) => !p.cancelled && (!supplier || p.supplierId === supplier) && (!status || p.status === status)); const totals = filtered.reduce((a, p) => ({ paid: a.paid + (p.status === 'pagado' ? p.amount : 0), pending: a.pending + (p.status === 'pendiente' || p.status === 'parcial' ? p.amount : 0), overdue: a.overdue + (p.status === 'vencido' ? p.amount : 0) }), { paid: 0, pending: 0, overdue: 0 }); const blank: Payment = { id: '', supplierId: state.suppliers[0]?.id || '', orderId: state.orders[0]?.id, amount: 0, date: today, method: 'transferencia', status: 'pendiente', reference: '', notes: '', responsible: users[0]?.name }; const save = () => { if (!editing || editing.amount <= 0 || !editing.supplierId) return notify('Completa proveedor y monto'); update((current) => ({ ...current, payments: current.payments.some((p) => p.id === editing.id) ? current.payments.map((p) => p.id === editing.id ? editing : p) : [...current.payments, { ...editing, id: `PAG-${String(current.payments.length + 1).padStart(3, '0')}` }] })); setEditing(null); notify('Pago guardado'); }; return <><div className="mb-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-3"><Metric title="Pagado" value={money(totals.paid)} note="Pagos confirmados" color="green" /><Metric title="Pendiente" value={money(totals.pending)} note="Pendiente y parcial" color="amber" /><Metric title="Vencido" value={money(totals.overdue)} note="Requiere gestión" color="red" /></div><Panel title="Pagos" subtitle="Responsable y trazabilidad local" action={<div className="flex flex-wrap gap-2"><select aria-label="Filtrar proveedor de pagos" className="field" value={supplier} onChange={(e) => setSupplier(e.target.value)}><option value="">Todos los proveedores</option>{state.suppliers.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}</select><select aria-label="Filtrar estado de pagos" className="field" value={status} onChange={(e) => setStatus(e.target.value)}><option value="">Todos los estados</option>{paymentStatuses.map((x) => <option key={x}>{x}</option>)}</select><button type="button" className="button-primary" onClick={() => setEditing({ ...blank })}>Nuevo pago</button><button type="button" className="button-secondary" onClick={exportCsv}>CSV</button></div>}>{filtered.length ? <div className="overflow-x-auto"><table className="data-table"><thead><tr><th>ID / proveedor</th><th>Monto</th><th>Fecha</th><th>Estado</th><th>Responsable</th><th /></tr></thead><tbody>{filtered.map((p) => <tr key={p.id}><td className="font-bold text-white">{p.id}<div className="text-xs font-normal">{supplierName(state.suppliers, p.supplierId)}</div></td><td>{money(p.amount)}</td><td>{dateEs(p.date)}</td><td><Badge value={p.status} /></td><td>{p.responsible || 'No asignado'}</td><td><button type="button" className="button-secondary" onClick={() => setEditing({ ...p })}>Editar</button></td></tr>)}</tbody></table></div> : <EmptyState text="No hay pagos para este filtro." />}</Panel>{editing && <Panel title="Registrar pago" subtitle="El usuario activo queda como responsable"><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><Field label="Proveedor"><select className="field w-full" value={editing.supplierId} onChange={(e) => setEditing({ ...editing, supplierId: e.target.value })}>{state.suppliers.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}</select></Field><Field label="Monto"><input className="field w-full" type="number" min="1" value={editing.amount} onChange={(e) => setEditing({ ...editing, amount: Number(e.target.value) })} /></Field><Field label="Método"><select className="field w-full" value={editing.method} onChange={(e) => setEditing({ ...editing, method: e.target.value as PaymentMethod })}>{paymentMethods.map((x) => <option key={x}>{x}</option>)}</select></Field><Field label="Estado"><select className="field w-full" value={editing.status} onChange={(e) => setEditing({ ...editing, status: e.target.value as PaymentStatus })}>{paymentStatuses.map((x) => <option key={x}>{x}</option>)}</select></Field><Field label="Responsable"><select className="field w-full" value={editing.responsible || ''} onChange={(e) => setEditing({ ...editing, responsible: e.target.value })}>{users.map((u) => <option key={u.id}>{u.name}</option>)}</select></Field><Field label="Fecha"><input className="field w-full" type="date" value={editing.date} onChange={(e) => setEditing({ ...editing, date: e.target.value })} /></Field></div><button type="button" className="button-primary mt-5" onClick={save}>Guardar pago</button></Panel>}</>; }
function Economy({ state, onNavigate }: { state: State; onNavigate: (s: Section) => void }) { const totals = finance(state); return <><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric title="Comprado" value={money(totals.purchased)} note="Valor de pedidos" color="amber" /><Metric title="Recibido" value={money(totals.received)} note="Valor de recepciones" color="green" /><Metric title="Pagado" value={money(totals.paid)} note="Pagos confirmados" /><Metric title="Saldo" value={money(totals.balance)} note="Comprado menos pagado" color="red" /></div><Panel title="Economía" subtitle="Resumen de operación local"><p className="text-sm text-slate-300">La demo separa comprado, recibido y pagado para facilitar conciliación.</p><button type="button" className="button-secondary mt-4" onClick={() => onNavigate('Pagos')}>Abrir pagos</button></Panel></>; }
function Agenda({ state, onNavigate }: { state: State; onNavigate: (s: Section) => void }) { const rows = state.orders.flatMap((o) => [{ date: o.expectedDate, title: `Pedido ${o.id}`, detail: supplierName(state.suppliers, o.supplierId), section: 'Pedidos' as Section }, ...state.receptions.filter((r) => r.orderId === o.id).map((r) => ({ date: (r.arrivedAt || r.createdAt).slice(0, 10), title: `Recepción ${o.id}`, detail: `${supplierName(state.suppliers, o.supplierId)} · ${r.arrivedAt ? 'Llegó' : 'Pendiente'}`, section: 'Recepcion' as Section }))]); return <Panel title="Agenda" subtitle="Pedidos y recepciones por fecha">{rows.length ? <div className="space-y-3">{rows.map((row, index) => <div key={`${row.title}-${index}`} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-white/10 p-4"><div><div className="text-xs font-bold uppercase tracking-wider text-cyan-300">{dateEs(row.date)}</div><div className="mt-1 font-bold text-white">{row.title}</div><div className="mt-1 text-sm text-slate-400">{row.detail}</div></div><button type="button" className="button-secondary" onClick={() => onNavigate(row.section)}>Abrir flujo</button></div>)}</div> : <EmptyState text="No hay eventos." />}</Panel>; }
function History({ state }: { state: State }) { const events = [...state.orders.map((o) => ({ date: o.createdAt, type: 'Pedido', title: `Pedido ${o.id}`, detail: supplierName(state.suppliers, o.supplierId) })), ...state.receptions.map((r) => ({ date: (r.arrivedAt || r.createdAt).slice(0, 10), type: 'Recepción', title: `Recepción ${r.orderId}`, detail: r.arrivedAt ? 'Llegada confirmada' : 'Recepción abierta' })), ...state.payments.filter((p) => !p.cancelled).map((p) => ({ date: p.date, type: 'Pago', title: `Pago ${p.id}`, detail: `${money(p.amount)} · ${supplierName(state.suppliers, p.supplierId)}` })), ...state.sources.map((s) => ({ date: s.date, type: 'Fuente', title: s.name, detail: `${s.kind} · ${s.status}` }))].sort((a, b) => b.date.localeCompare(a.date)); return <Panel title="Historial" subtitle="Pedidos, recepciones, pagos y fuentes">{events.length ? <div className="space-y-2">{events.map((e, i) => <div key={`${e.type}-${e.title}-${i}`} className="flex gap-3 rounded-lg border border-white/10 p-3"><span className="text-xs text-cyan-300">{dateEs(e.date)}</span><div><div className="font-semibold text-white">{e.title}</div><div className="text-xs text-slate-400">{e.detail}</div></div></div>)}</div> : <EmptyState text="No hay eventos." />}</Panel>; }
function Generic({ section, state }: { section: Section; state: State }) { return <Panel title={section} subtitle="Módulo operativo de Control de Abastecimiento"><EmptyState text={`${state.products.length} productos, ${state.orders.length} pedidos y ${state.suppliers.length} proveedores disponibles.`} /></Panel>; }
function paymentLabel(state: State, orderId: string) { const payments = state.payments.filter((p) => p.orderId === orderId && !p.cancelled); if (payments.some((p) => p.status === 'pagado')) return 'pagado'; if (payments.some((p) => p.status === 'vencido')) return 'vencido'; if (payments.length) return 'parcial'; return 'pendiente'; }
function finance(state: State) { const purchased = state.orders.reduce((a, o) => a + orderTotal(o), 0); const orderIds = new Set(state.orders.map((o) => o.id)); const received = state.receptions.filter((r) => orderIds.has(r.orderId)).reduce((total, r) => { const order = state.orders.find((o) => o.id === r.orderId); return total + (order ? r.lines.reduce((sum, line) => sum + line.received * (order.lines.find((x) => x.id === line.orderLineId)?.price || 0), 0) : 0); }, 0); const paid = state.payments.filter((p) => !p.cancelled && p.status === 'pagado').reduce((a, p) => a + p.amount, 0); return { purchased, received, paid, balance: Math.max(purchased - paid, 0) }; }

function Settings({ clearLocalData, notify, installPromptAvailable, installed, onInstallPrompt }: { clearLocalData: () => void; notify: (message: string) => void; installPromptAvailable: boolean; installed: boolean; onInstallPrompt: () => Promise<void> }) {
  const [confirmOpen, setConfirmOpen] = useState(false); const [restoreOpen, setRestoreOpen] = useState(false); const [confirmation, setConfirmation] = useState(''); const [lastSaved, setLastSaved] = useState<string | null>(null);
  useEffect(() => { setLastSaved(window.localStorage.getItem('zavryon-abastecimiento-demo-v6-saved-at')); }, []);
  const requestClear = () => { if (window.confirm('¿Seguro que quieres borrar los datos?')) { setConfirmation(''); setConfirmOpen(true); } };
  const clear = () => { if (confirmation !== 'BORRAR') return; clearLocalData(); setConfirmOpen(false); setConfirmation(''); notify('Datos locales borrados. La aplicación quedó lista para comenzar de nuevo.'); };
  const requestRestore = () => { if (window.confirm('Restaurar demo sobrescribirá todos los datos locales de este navegador. ¿Continuar?')) { setConfirmation(''); setRestoreOpen(true); } };
  const restore = () => { if (confirmation !== 'RESTAURAR') return; window.dispatchEvent(new Event('restore-demo')); setRestoreOpen(false); setConfirmation(''); notify('Datos demo restaurados.'); };
  return <>
    <Panel title="Configuración y administración" subtitle="Controla la demo local de este navegador sin afectar datos remotos">
       <div className="mb-5 grid gap-3 sm:grid-cols-2"><div className="rounded-xl border border-white/10 p-4"><h4 className="font-bold text-white">Persistencia local</h4><p className="mt-2 text-sm text-slate-300">{lastSaved ? `Último guardado local: ${new Date(lastSaved).toLocaleString('es-CO')}` : 'Último guardado local: pendiente'}</p><p className="mt-2 text-xs text-emerald-200">Guardado inmediato en cada actualización con copia de recuperación ante JSON corrupto o cierre inesperado.</p></div><div className="rounded-xl border border-cyan-300/30 bg-cyan-400/5 p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><h4 className="font-bold text-white">Instalar aplicación en Android</h4><p className="mt-2 text-sm leading-6 text-slate-300">Instala esta aplicación como PWA desde el navegador. No se genera ni descarga un APK independiente.</p></div>{installed ? <span className="badge-green" role="status">Instalada</span> : null}</div>{installed ? <p className="mt-4 text-sm text-emerald-200" role="status">La aplicación ya está instalada en este dispositivo.</p> : installPromptAvailable ? <button type="button" className="button-primary mt-4" onClick={() => void onInstallPrompt()}>Instalar aplicación</button> : <><button type="button" className="button-secondary mt-4 cursor-not-allowed opacity-60" disabled aria-describedby="android-install-help">Instalación directa no disponible</button><p id="android-install-help" className="mt-3 text-sm leading-6 text-slate-300">En Chrome Android, abre esta URL HTTPS, toca el menú ⋮ y elige <strong className="text-white">Instalar aplicación</strong> o <strong className="text-white">Agregar a pantalla principal</strong>.</p></>}<p className="mt-3 text-xs leading-5 text-slate-400">La opción automática aparece cuando el navegador cumple los requisitos de instalación. En localhost puede no estar disponible; usa HTTPS para instalar.</p></div></div>
      <div className="rounded-xl border border-red-400/40 bg-red-950/20 p-5"><div className="flex items-start gap-3"><TrashIcon className="mt-0.5 h-5 w-5 shrink-0 text-red-300" aria-hidden="true" /><div><h4 className="font-bold text-white">Borrar datos</h4><p className="mt-1 text-sm leading-6 text-slate-300">Elimina proveedores, productos, relaciones, pedidos, recepciones, vencimientos, fuentes, candidatos, pagos, usuarios, configuración, preferencias y alertas guardadas localmente.</p><p className="mt-3 text-xs leading-5 text-red-200">Esto borra los datos locales de este navegador. La eliminación remota requiere una acción separada de administrador.</p><button type="button" className="button-danger mt-4" onClick={requestClear}>Borrar datos</button></div></div></div>
    </Panel>
    {confirmOpen && <div className="modal-backdrop" role="presentation"><div className="modal-card" role="dialog" aria-modal="true" aria-labelledby="delete-data-title" aria-describedby="delete-data-description"><h3 id="delete-data-title" className="text-lg font-bold text-white">Confirmar borrado de datos</h3><p id="delete-data-description" className="mt-3 text-sm leading-6 text-slate-300">Esta acción no se puede deshacer. Escribe <strong className="text-white">BORRAR</strong> para confirmar. Se conservará únicamente un administrador mínimo para recuperar el acceso.</p><label className="mt-4 block text-xs font-semibold text-slate-300" htmlFor="delete-confirmation">Escribe BORRAR</label><input id="delete-confirmation" className="field mt-1 w-full" value={confirmation} onChange={(event) => setConfirmation(event.target.value)} autoComplete="off" autoFocus /><div className="mt-5 flex justify-end gap-2"><button type="button" className="button-secondary" onClick={() => setConfirmOpen(false)}>Cancelar</button><button type="button" className="button-danger" disabled={confirmation !== 'BORRAR'} onClick={clear}>Borrar definitivamente</button></div></div></div>}
    {restoreOpen && <div className="modal-backdrop" role="presentation"><div className="modal-card" role="dialog" aria-modal="true" aria-labelledby="restore-demo-title"><h3 id="restore-demo-title" className="text-lg font-bold text-white">Confirmar restauración demo</h3><p className="mt-3 text-sm leading-6 text-slate-300">Se sobrescribirán los datos locales actuales. Escribe <strong className="text-white">RESTAURAR</strong> para continuar.</p><input aria-label="Escribe RESTAURAR" className="field mt-4 w-full" value={confirmation} onChange={(event) => setConfirmation(event.target.value)} autoComplete="off" autoFocus /><div className="mt-5 flex justify-end gap-2"><button type="button" className="button-secondary" onClick={() => setRestoreOpen(false)}>Cancelar</button><button type="button" className="button-primary" disabled={confirmation !== 'RESTAURAR'} onClick={restore}>Restaurar demo</button></div></div></div>}
  </>;
}
